--
-- Name: get_proximo_numero_nfe(bigint, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_proximo_numero_nfe(p_cliente_id bigint, p_modelo character varying, p_serie integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_proximo_numero INTEGER;
BEGIN
    -- Buscar o maior número existente para o cliente, modelo e série
    SELECT COALESCE(MAX(numero), 0) + 1
    INTO v_proximo_numero
    FROM nfe_emitidas
    WHERE cliente_id = p_cliente_id
      AND modelo = p_modelo
      AND serie = p_serie;
    
    RETURN v_proximo_numero;
END;
$$;


