--
-- Name: limpar_auditoria_antiga(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.limpar_auditoria_antiga() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    registros_deletados INTEGER;
BEGIN
    -- Deleta registros com mais de 365 dias
    DELETE FROM auditoria
    WHERE timestamp < NOW() - INTERVAL '365 days';
    
    GET DIAGNOSTICS registros_deletados = ROW_COUNT;
    RETURN registros_deletados;
END;
$$;


