--
-- Name: registrar_emissao_nfe(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_emissao_nfe(p_cliente_id bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_assinatura_id INTEGER;
BEGIN
    -- Buscar assinatura ativa
    SELECT assinatura_id INTO v_assinatura_id
    FROM assinaturas_cliente
    WHERE cliente_id = p_cliente_id 
      AND status = 'ATIVA'
      AND (data_fim IS NULL OR data_fim >= CURRENT_DATE)
    ORDER BY assinatura_id DESC
    LIMIT 1;
    
    IF FOUND THEN
        -- Incrementar contador
        UPDATE assinaturas_cliente
        SET nfes_consumidas = nfes_consumidas + 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE assinatura_id = v_assinatura_id;
        
        RETURN true;
    ELSE
        RETURN false;
    END IF;
END;
$$;


