--
-- Name: renovar_periodo_assinatura(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renovar_periodo_assinatura(p_assinatura_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE assinaturas_cliente
    SET nfes_consumidas = 0,
        periodo_ref_inicio = CURRENT_DATE,
        periodo_ref_fim = CURRENT_DATE + INTERVAL '1 month',
        updated_at = CURRENT_TIMESTAMP
    WHERE assinatura_id = p_assinatura_id;
    
    RETURN FOUND;
END;
$$;


