--
-- Name: vw_resumo_faturamento_cliente; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_resumo_faturamento_cliente AS
 SELECT c.cliente_id,
    c.razao_social,
    c.cnpj,
    cfg.valor_por_nfe,
    cfg.forma_pagamento,
    cfg.dia_vencimento,
    cfg.ativo AS config_ativa,
    count(DISTINCT fm.faturamento_id) AS total_faturas,
    count(DISTINCT
        CASE
            WHEN ((fm.status_pagamento)::text = 'pago'::text) THEN fm.faturamento_id
            ELSE NULL::integer
        END) AS faturas_pagas,
    count(DISTINCT
        CASE
            WHEN ((fm.status_pagamento)::text = 'pendente'::text) THEN fm.faturamento_id
            ELSE NULL::integer
        END) AS faturas_pendentes,
    count(DISTINCT
        CASE
            WHEN ((fm.status_pagamento)::text = 'vencido'::text) THEN fm.faturamento_id
            ELSE NULL::integer
        END) AS faturas_vencidas,
    COALESCE(sum(fm.valor_total), (0)::numeric) AS valor_total_faturado,
    COALESCE(sum(
        CASE
            WHEN ((fm.status_pagamento)::text = 'pago'::text) THEN fm.valor_total
            ELSE (0)::numeric
        END), (0)::numeric) AS valor_total_pago,
    COALESCE(sum(
        CASE
            WHEN ((fm.status_pagamento)::text = ANY (ARRAY[('pendente'::character varying)::text, ('vencido'::character varying)::text])) THEN fm.valor_total
            ELSE (0)::numeric
        END), (0)::numeric) AS valor_total_pendente
   FROM ((public.clientes c
     LEFT JOIN public.cliente_configuracao_faturamento cfg ON ((c.cliente_id = cfg.cliente_id)))
     LEFT JOIN public.faturamento_mensal fm ON ((c.cliente_id = fm.cliente_id)))
  GROUP BY c.cliente_id, c.razao_social, c.cnpj, cfg.valor_por_nfe, cfg.forma_pagamento, cfg.dia_vencimento, cfg.ativo;


--
-- Name: VIEW vw_resumo_faturamento_cliente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.vw_resumo_faturamento_cliente IS 'View com resumo consolidado de faturamento por cliente';


